package com.sami.app.purchasing.web; import com.sami.app.common.api.ApiResponse; import com.sami.app.purchasing.service.GoodsReceiptService; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/goods-receipts") @RequiredArgsConstructor public class GoodsReceiptController{private final GoodsReceiptService service;@GetMapping @PreAuthorize("@authz.has('purchasing:view')") public ApiResponse<List<Map<String,Object>>> list(){return ApiResponse.ok(service.list());}@GetMapping("/{id}") @PreAuthorize("@authz.has('purchasing:view')") public ApiResponse<Map<String,Object>> get(@PathVariable Long id){return ApiResponse.ok(service.get(id));}@PostMapping @PreAuthorize("@authz.has('purchasing:create')") public ApiResponse<Map<String,Object>> create(@RequestParam Long companyId,@RequestParam Long branchId,@RequestParam Long purchaseOrderId,@RequestParam(required=false) Long warehouseId,@RequestBody Map<String,Object> body){return ApiResponse.ok(service.create(companyId,branchId,purchaseOrderId,warehouseId,(List<Map<String,Object>>)body.get("lines"),(String)body.get("notes")));}}
